llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C59"],
      "claim": "KNI-272, a structurally related peptidomimetic HIV protease inhibitor with a tert-butyl carboxamide and hydroxyethylamine core, showed absolute oral bioavailability of 36.40% when given post-prandially in patients, directly supporting F ≥ 20% for the query under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Indinavir, another HIV protease inhibitor, had systemic bioavailability of 0.60 (0.54–0.66) after oral dosing in humans, supporting the expectation that this peptidomimetic class can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Boceprevir, a peptidomimetic protease inhibitor, had an estimated oral bioavailability of approximately 20% in humans, which is at the threshold and supports a high prediction for F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Remikiren, a peptidomimetic renin inhibitor, had an absolute bioavailability of only 0.3% in healthy volunteers, providing a contradictory low-bioavailability example; however, its very low F reflects distinct physicochemical and first-pass liabilities and lower structural transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "KNI-272 in children showed a mean absolute bioavailability of 12% (range 3.5–25%), a contradictory low value, but pediatric age, formulation, and dosing conditions limit its transferability to the adult fed-state query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a peptidomimetic HIV protease inhibitor with a tert-butyl carboxamide and hydroxyethylamine core. The closest related HIV protease inhibitor KNI-272 showed post-prandial absolute F of 36.4% and adult F values mostly 29–55%; indinavir and boceprevir also support F ≥ 20%. Low-F analogues such as remikiren and pediatric KNI-272 are less transferable due to distinct chemotypes or conditions. Overall, the evidence supports high oral bioavailability at the F ≥ 20% threshold, especially in the fed state.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is provided; all evidence comes from analogues with low Morgan similarity.",
    "Pediatric low-F data for KNI-272 may not translate to adult fed-state conditions.",
    "The fed-state effect is inferred from post-prandial KNI-272 data and general food effects rather than from direct query-specific fed-state measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

